    33→
    34→function createBubbleChart(data) {
    35→    // Setup scales
    36→    const radiusScale = d3.scaleSqrt()
    37→        .domain([0, d3.max(data, d => d.value || 0)])
    38→        .range([5, 50]);
    39→
    40→    const colorScale = d3.scaleOrdinal()
    41→        .domain([...new Set(data.map(d => d.sector))])
    42→        .range(d3.schemeCategory10);
    43→
    44→    // Calculate radius for each data point
    45→    data.forEach(d => {
    46→        if (d.value === null || isNaN(d.value)) {
    47→            d.radius = 10; // Uniform size for missing data
    48→            d.hasValue = false;
    49→        } else {
    50→            d.radius = radiusScale(d.value);
    51→            d.hasValue = true;
    52→        }
    53→    });
    54→
    55→    // Create force simulation
    56→    const simulation = d3.forceSimulation(data)
    57→        .force('center', d3.forceCenter(width / 2, height / 2))
    58→        .force('collide', d3.forceCollide(d => d.radius + 2))
    59→        .force('charge', d3.forceManyBody().strength(-30));
    60→
    61→    // Optional: Cluster by sector
    62→    const sectors = [...new Set(data.map(d => d.sector))];
    63→    const sectorPositions = {};
    64→    sectors.forEach((sector, i) => {
    65→        const angle = (i / sectors.length) * 2 * Math.PI;
    66→        sectorPositions[sector] = {
    67→            x: width / 2 + Math.cos(angle) * 150,
    68→            y: height / 2 + Math.sin(angle) * 150
