    75→
    76→    // Create bubbles
    77→    const bubbles = svg.selectAll('circle')
    78→        .data(data)
    79→        .join('circle')
    80→        .attr('class', 'bubble')
    81→        .attr('r', d => d.radius)
    82→        .attr('fill', d => colorScale(d.sector))
    83→        .attr('opacity', 0.7)
