document.addEventListener("DOMContentLoaded", () => {
    d3.csv("data/stock-descriptions.csv").then(data => {
        // Prepare container dimensions
        const chartContainer = document.getElementById('bubble-chart-container');
        const width = chartContainer.clientWidth;
        const height = chartContainer.clientHeight;

        const svg = d3.select('#bubble-chart')
            .attr('width', width)
            .attr('height', height);

        // Process data
        const sectors = Array.from(new Set(data.map(d => d.sector)));
        const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

        const maxMarketCap = d3.max(data, d => +d.marketCap || 0);
        const radiusScale = d3.scaleSqrt()
            .domain([0, maxMarketCap])
            .range([15, 60]);

        const etfSize = 25;

        data.forEach(d => {
            if (d.sector === 'ETF') {
                d.radius = etfSize;
            } else {
                d.radius = radiusScale(+d.marketCap) || 20;
            }
        });

        // Compute sector focal points for clustering
        const radius = Math.min(width, height) / 3;
        const sectorFoci = {};
        sectors.forEach((sector, i) => {
            const angle = (i / sectors.length) * 2 * Math.PI;
            sectorFoci[sector] = {
                x: width / 2 + Math.cos(angle) * radius,
                y: height / 2 + Math.sin(angle) * radius
            };
        });

        // Force simulation
        const simulation = d3.forceSimulation(data)
            .force('x', d3.forceX(d => sectorFoci[d.sector].x).strength(0.1))
            .force('y', d3.forceY(d => sectorFoci[d.sector].y).strength(0.1))
            .force('collide', d3.forceCollide(d => d.radius + 2).iterations(4))
            .force('center', d3.forceCenter(width / 2, height / 2).strength(0.01));

        // Create bubbles
        const node = svg.append('g')
            .selectAll('g')
            .data(data)
            .enter()
            .append('g')
            .attr('id', d => `bubble-${d.ticker}`)
            .attr('class', 'bubble');

        node.append('circle')
            .attr('r', d => d.radius)
            .attr('fill', d => colorScale(d.sector));

        node.append('text')
            .attr('class', 'bubble-label')
            .attr('dy', '0.3em')
            .attr('font-size', d => Math.min(2 * d.radius, (2 * d.radius - 8) / this.getComputedTextLength() * 12) + "px") // dynamic font sizing can be tricky, simpler approach:
            .text(d => d.ticker);

        // Fix font size based on radius
        node.selectAll('text').attr('font-size', function(d) {
            return Math.min(14, d.radius * 0.8) + "px";
        });

        // Tooltip
        const tooltip = d3.select('#tooltip');

        node.on('mouseover', function(event, d) {
            if (d.sector === 'ETF') return;

            tooltip.transition().duration(200).style('opacity', 0.9);
            tooltip.html(`<strong>${d.ticker}</strong><br/>${d['full name']}<br/>${d.sector}`)
                .style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY - 28) + 'px');
        })
        .on('mousemove', function(event) {
            tooltip.style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY - 28) + 'px');
        })
        .on('mouseout', function(event, d) {
            if (d.sector === 'ETF') return;
            tooltip.transition().duration(500).style('opacity', 0);
        });

        simulation.on('tick', () => {
            node.attr('transform', d => `translate(${d.x}, ${d.y})`);
        });

        // Legend
        const legend = svg.append('g')
            .attr('class', 'legend')
            .attr('transform', 'translate(20, 20)');

        sectors.forEach((sector, i) => {
            const legendRow = legend.append('g')
                .attr('transform', `translate(0, ${i * 25})`);

            legendRow.append('rect')
                .attr('width', 15)
                .attr('height', 15)
                .attr('fill', colorScale(sector));

            legendRow.append('text')
                .attr('x', 25)
                .attr('y', 12)
                .attr('text-anchor', 'start')
                .attr('class', 'legend-item')
                .text(sector);
        });

        // Table logic
        function formatMarketCap(value) {
            if (!value || isNaN(value)) return 'N/A';
            if (value >= 1e12) return (value / 1e12).toFixed(2) + 'T';
            if (value >= 1e9) return (value / 1e9).toFixed(2) + 'B';
            if (value >= 1e6) return (value / 1e6).toFixed(2) + 'M';
            return value.toLocaleString();
        }

        const tbody = d3.select('#data-table tbody');
        const rows = tbody.selectAll('tr')
            .data(data)
            .enter()
            .append('tr')
            .attr('id', d => `row-${d.ticker}`);

        rows.append('td').text(d => d.ticker);
        rows.append('td').text(d => d['full name']);
        rows.append('td').text(d => d.sector);
        rows.append('td').text(d => formatMarketCap(+d.marketCap));

        // Interactivity between chart and table
        node.on('click', function(event, d) {
            // highlight bubble
            node.classed('highlighted', false);
            d3.select(this).classed('highlighted', true);

            // highlight row
            rows.classed('highlighted', false);
            const targetRow = d3.select(`#row-${d.ticker}`);
            targetRow.classed('highlighted', true);
            targetRow.node().scrollIntoView({ behavior: 'smooth', block: 'center' });
        });

        rows.on('click', function(event, d) {
            // highlight row
            rows.classed('highlighted', false);
            d3.select(this).classed('highlighted', true);

            // highlight bubble
            node.classed('highlighted', false);
            d3.select(`#bubble-${d.ticker}`).classed('highlighted', true);
        });
    });
});
