    .scaleOrdinal()
    .domain(sectors)
    .range(["#2878b5", "#6f5aa6", "#2f8f68", "#c65f39", "#7f8b98"]);

  let stockData = [];
  let activeTicker = null;
  let resizeTimer = null;

  const capFormatter = d3.format(".3s");

  function normalizeRow(row) {
    const rawCap = row.marketCap;
    const marketCap =
      rawCap === null || rawCap === undefined || rawCap === ""
        ? null
        : Number(rawCap);

    return {
      ticker: String(row.ticker || "").trim().toUpperCase(),
      fullName: row.fullName || row["full name"] || "",
      sector: row.sector || "ETF",
      marketCap: Number.isFinite(marketCap) ? marketCap : null
    };
  }

  function formatMarketCap(value) {
    if (!Number.isFinite(value)) {
      return "ETF";
    }

    return capFormatter(value).replace("G", "B").replace("T", "T");
  }

  function loadRows() {
    if (window.location.protocol === "file:") {
      return Promise.resolve(embeddedRows);
