      return embeddedRows;
    });
  }

  function drawLegend() {
    const items = legend.selectAll(".legend-item").data(sectors, function (d) {
      return d;
    });

    const enter = items
      .enter()
      .append("div")
      .attr("class", "legend-item");

    enter
      .append("span")
      .attr("class", "legend-swatch")
      .style("background-color", function (d) {
        return color(d);
      });

    enter.append("span").text(function (d) {
      return d;
    });
  }

  function drawTable(data) {
    const rows = tableBody
      .selectAll("tr")
      .data(data, function (d) {
        return d.ticker;
