      d.x = Math.max(d.radius + 10, Math.min(width - d.radius - 10, d.x));
      d.y = Math.max(d.radius + 24, Math.min(height - d.radius - 10, d.y));
    });

    const svg = chartRoot
      .selectAll("svg")
      .data([null])
      .join("svg")
      .attr("viewBox", "0 0 " + width + " " + height)
      .attr("role", "img")
