      .data(sectors)
      .join("text")
      .attr("class", "cluster-label")
      .attr("x", function (d) {
        return centers.get(d).x;
      })
      .attr("y", function (d) {
        return Math.max(18, centers.get(d).y - 96);
      })
      .text(function (d) {
        return d;
      });

    const groups = svg
      .append("g")
      .attr("class", "bubbles")
      .selectAll("g")
      .data(nodes, function (d) {
        return d.ticker;
      })
      .join("g")
      .attr("transform", function (d) {
        return "translate(" + d.x + "," + d.y + ")";
      });

