      .append("circle")
      .attr("class", function (d) {
        return "bubble" + (d.ticker === activeTicker ? " is-active" : "");
      })
      .attr("r", function (d) {
        return d.radius;
      })
      .attr("fill", function (d) {
        return color(d.sector);
      })
      .on("mouseenter", function (event, d) {
        if (d.marketCap === null) {
          return;
        }

        tooltip
          .html(
            "<strong>" +
              d.ticker +
              "</strong><span>" +
              d.fullName +
              "</span><span>" +
              d.sector +
              "</span>"
          )
          .classed("is-visible", true);
        moveTooltip(event);
      })
      .on("mousemove", moveTooltip)
      .on("mouseleave", function () {
        tooltip.classed("is-visible", false);
      })
      .on("click", function (event, d) {
        setActive(d.ticker, true);
      });

    groups
      .append("text")
      .attr("class", "bubble-label")
      .style("font-size", function (d) {
        return d.labelSize + "px";
      })
      .text(function (d) {
        return d.ticker;
      });

    updateActiveStyles(false);
  }

  function moveTooltip(event) {
    tooltip
      .style("left", event.clientX + "px")
      .style("top", event.clientY + "px");
  }

  function setActive(ticker, shouldScroll) {
    activeTicker = ticker;
    updateActiveStyles(shouldScroll);
  }

  function updateActiveStyles(shouldScroll) {
    d3.selectAll(".bubble").classed("is-active", function (d) {
      return d && d.ticker === activeTicker;
    });

    const rows = tableBody.selectAll("tr").classed("is-active", function (d) {
      return d.ticker === activeTicker;
    });

    if (shouldScroll && activeTicker) {
      const activeRow = rows
        .filter(function (d) {
          return d.ticker === activeTicker;
        })
        .node();

      if (activeRow) {
        activeRow.scrollIntoView({ block: "nearest", behavior: "smooth" });
      }
    }
  }

  function handleResize() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(drawChart, 120);
  }

  loadRows().then(function (rows) {
    stockData = rows.map(normalizeRow).filter(function (d) {
      return d.ticker;
    });

    drawLegend();
    drawTable(stockData);
    drawChart();
    window.addEventListener("resize", handleResize);
  });
})();
